<script setup lang="ts">
import { teacherText } from '~/utils/teacher-language'
import type { SavedRequest } from '~/utils/scenario-constructor'
import { createGenerationLauncher } from '~/utils/generation-launcher'
const props = defineProps<{ request: SavedRequest }>()
const auth = useAuthStore(), api = useGenerationApi(), route = useRoute()
const context = () => `${auth.user?.id ?? ''}:${auth.tenant?.school_id ?? ''}:${props.request.id}`
const launcher = createGenerationLauncher(context, { getItem: key => window.localStorage.getItem(key), setItem: (key, value) => window.localStorage.setItem(key, value) })
const { receipt, pending, error } = launcher, confirm = ref(false)
const canLaunch = computed(() => props.request.school_id === auth.tenant?.school_id && (props.request.user_id === auth.user?.id || auth.systemRole === 'system_admin'))
watch(context, () => { confirm.value = false; launcher.reset() }, { immediate: true, flush: 'sync' })
const previousId = computed(() => receipt.value?.runId ?? (typeof route.query.retry_run === 'string' ? route.query.retry_run : ''))
const previous = useSchoolResource(async signal => { const run = await api.run(previousId.value, auth.tenant!.school_id, signal); if (run.scenario_request_id !== props.request.id) throw new Error('Предыдущая попытка относится к другому запросу.'); return run }, () => [context(), previousId.value], () => !!previousId.value)
const canRetryNew = computed(() => previous.data.value && ['failed', 'timed_out'].includes(previous.data.value.status))
async function launch() { confirm.value = false; const id = props.request.id, schoolId = auth.tenant!.school_id; await launcher.launch((key, signal) => api.launch(id, schoolId, key, signal), canRetryNew.value ? previous.data.value! : undefined) }
function storageChanged(event: StorageEvent) { if (!pending.value && event.key?.startsWith('fe006:generation:')) launcher.reset() }
onMounted(() => window.addEventListener('storage', storageChanged))
onBeforeUnmount(() => { window.removeEventListener('storage', storageChanged); launcher.reset() })
</script>
<template><section class="generation-launch" aria-labelledby="generation-launch-title"><h2 id="generation-launch-title">Подготовить сценарий</h2><p>Запуск использует сохранённые параметры, показанные выше. Результат нужно проверить перед проведением.</p><UiAlert v-if="!canLaunch" tone="warning">Запуск доступен автору запроса или системному администратору.</UiAlert><UiAlert v-if="error" tone="error">{{ teacherText(error.message) }}</UiAlert><template v-if="receipt?.runId"><NuxtLink :to="`/generation-runs/${receipt.runId}`" class="ui-button ui-button--primary">Открыть состояние генерации</NuxtLink></template><NuxtLink v-else-if="receipt?.scenarioId" :to="`/scenarios/${receipt.scenarioId}`" class="ui-button ui-button--primary">Открыть существующий сценарий</NuxtLink><UiAlert v-else-if="receipt && !pending" tone="warning"><strong>{{ receipt.phase === 'rejected' ? 'Запуск не принят' : 'Результат запуска неизвестен' }}</strong><p>Проверка прежнего запуска не создаёт дубликат. Проверить его можно в течение 23 часов.</p></UiAlert><UiAlert v-if="canRetryNew" tone="warning">Предыдущая попытка завершена сервером без результата. Для новой попытки нужно ваше подтверждение.</UiAlert><UiButton v-if="canLaunch && ((!receipt?.runId && !receipt?.scenarioId) || canRetryNew)" :loading="pending" :disabled="error?.code === 'GENERATION_STORAGE' || previous.pending.value" @click="confirm = true">{{ pending ? 'Отправляем запрос' : canRetryNew ? 'Новая попытка после ошибки' : receipt ? 'Проверить прежний запуск' : 'Запустить генерацию' }}</UiButton><UiModal v-model="confirm" :title="canRetryNew ? 'Подтвердить новую попытку?' : receipt ? 'Восстановить прежний запуск?' : 'Запустить генерацию?' "><p>Подготовить сценарий по указанным выше условиям для школы {{ auth.tenant?.school_name }}?</p><p>Созданные материалы являются проектом и требуют оценки педагога. Сохранение запроса само по себе не запускает генерацию.</p><div class="actions"><UiButton variant="secondary" @click="confirm = false">Вернуться к параметрам</UiButton><UiButton @click="launch">{{ receipt && !canRetryNew ? 'Восстановить запуск' : 'Подтвердить запуск' }}</UiButton></div></UiModal></section></template>
